    host: "ldap.internal.svc.cluster.local",
    port: 636,
    baseDN: "dc=company,dc=internal",
    bindDN: "cn=search-indexer,ou=services,dc=company,dc=internal",
    bindPassword: ProcessInfo.processInfo.environment["LDAP_BIND_PASSWORD"] ?? "",
    useTLS: true
)

let service = LDAPSearchIndexService(config: config)
let handler = K8sServiceHandler(searchService: service)

